-- Project Management baseline for the `project` schema on the shared GrowSpark database.
-- Generated by scripts/shared-db/build-baseline.mjs from the schema built by supabase/migrations
-- (34 migrations, last 20261122001300) and supabase/seed.sql. Review changes in this file, not in the dump.
--
-- Run as project_migrator (owner of everything created here), after db/shared/roles.sql.
-- Removed: SCHEMA public; COMMENT SCHEMA public; FUNCTION handle_new_user(); COMMENT FUNCTION handle_new_user(); FK CONSTRAINT user_profiles user_profiles_id_fkey; ACL SCHEMA public; ACL FUNCTION handle_new_user(); Supabase DEFAULT ACL DEFAULT PRIVILEGES FOR SEQUENCES; Supabase DEFAULT ACL DEFAULT PRIVILEGES FOR SEQUENCES; Supabase DEFAULT ACL DEFAULT PRIVILEGES FOR FUNCTIONS; Supabase DEFAULT ACL DEFAULT PRIVILEGES FOR FUNCTIONS; Supabase DEFAULT ACL DEFAULT PRIVILEGES FOR TABLES; Supabase DEFAULT ACL DEFAULT PRIVILEGES FOR TABLES.

-- All or nothing: a failure part-way leaves nothing behind.
BEGIN;

SET LOCAL statement_timeout = 0;
SET LOCAL lock_timeout = 0;
SET LOCAL idle_in_transaction_session_timeout = 0;
SET LOCAL transaction_timeout = 0;
SET LOCAL client_encoding = 'UTF8';
SET LOCAL standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', true);
SET LOCAL check_function_bodies = false;
SET LOCAL xmloption = content;
SET LOCAL client_min_messages = warning;
SET LOCAL row_security = off;

-- Who is asking. The server sets these per request, inside the transaction (lib/db withUser / withAnon /
-- withSystem), as PostgREST does from a verified JWT. No SET search_path: the bodies use only pg_catalog,
-- which keeps them inlinable in policies.
CREATE FUNCTION project.current_user_id() RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  SELECT nullif(coalesce(
    nullif(pg_catalog.current_setting('request.jwt.claim.sub', true), ''),
    nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub'
  ), '')::uuid
$$;
COMMENT ON FUNCTION project.current_user_id() IS 'The signed-in user''s id for this request (replaces auth.uid()); NULL when signed out or for server jobs.';

-- The request's role. The database role decides first, so a project_user request can never pass as a
-- trusted server job even without claims; claims are used only for other roles (the rehearsal harness).
CREATE FUNCTION project.request_role() RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE pg_catalog.current_setting('role', true)
    WHEN 'project_user' THEN 'authenticated'
    WHEN 'project_anon' THEN 'anon'
    WHEN 'project_system' THEN 'service_role'
    ELSE coalesce(
      nullif(pg_catalog.current_setting('request.jwt.claim.role', true), ''),
      nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb ->> 'role')
  END
$$;
COMMENT ON FUNCTION project.request_role() IS 'authenticated / anon / service_role for this request (replaces auth.role()).';

-- FUNCTION: audit_log_append_only()
CREATE FUNCTION project.audit_log_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.actor_id IS NOT NULL AND NEW.actor_id IS NULL
     AND NEW.id = OLD.id
     AND NEW.action = OLD.action
     AND NEW.entity_type = OLD.entity_type
     AND NEW.entity_id IS NOT DISTINCT FROM OLD.entity_id
     AND NEW.project_id IS NOT DISTINCT FROM OLD.project_id
     AND NEW.details = OLD.details
     AND NEW.created_at = OLD.created_at
  THEN
    NEW.details := OLD.details || jsonb_build_object('deleted_actor_id', OLD.actor_id);
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'The audit log is append-only' USING ERRCODE = '42501';
END;
$$;

-- FUNCTION: auto_clock_out_stale_sessions()
CREATE FUNCTION project.auto_clock_out_stale_sessions() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  UPDATE project.clock_sessions
  SET
    clock_out_time = clock_in_time + INTERVAL '16 hours',
    is_active = false,
    is_auto_clock_out = true
  WHERE is_active = true
    AND clock_in_time < NOW() - INTERVAL '16 hours';
END;
$$;

-- COMMENT: FUNCTION auto_clock_out_stale_sessions()
COMMENT ON FUNCTION project.auto_clock_out_stale_sessions() IS 'Automatically closes clock sessions that have been active for more than 16 hours. Prevents overnight sessions from corrupting data.';

-- FUNCTION: caller_holds_permissions(jsonb)
CREATE FUNCTION project.caller_holds_permissions(perms jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
  SELECT NOT EXISTS (
    SELECT 1 FROM jsonb_each(COALESCE(perms, '{}'::jsonb)) AS p(key, value)
    WHERE p.value = 'true'::jsonb AND NOT project.user_has_permission(p.key)
  );
$$;

-- FUNCTION: caller_is_trusted()
CREATE FUNCTION project.caller_is_trusted() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'project', 'pg_temp'
    AS $$
  SELECT COALESCE(project.request_role(), '') = 'service_role'
      OR (project.current_user_id() IS NULL AND COALESCE(project.request_role(), '') NOT IN ('anon', 'authenticated'));
$$;

-- FUNCTION: complete_project_when_workflow_completes()
CREATE FUNCTION project.complete_project_when_workflow_completes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status = 'completed' AND OLD.status IS DISTINCT FROM 'completed' AND NEW.project_id IS NOT NULL THEN
    UPDATE project.projects
       SET status = 'complete',
           completed_at = COALESCE(completed_at, NEW.completed_at, now()),
           updated_at = now()
     WHERE id = NEW.project_id
       AND status IS DISTINCT FROM 'complete';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: complete_workspace_registration(uuid, text, text, text)
CREATE FUNCTION project.complete_workspace_registration(p_user_id uuid, p_email text, p_name text, p_phone text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE
  v_role uuid;
BEGIN
  -- The claim must be held and not finished yet; the row lock serialises two finishers.
  PERFORM 1 FROM app_settings
   WHERE id = true AND registered_at IS NOT NULL AND registered_by IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No company registration is in progress' USING ERRCODE = '55000';
  END IF;

  -- Only the new manager may exist (the auth trigger has just created their profile).
  IF EXISTS (SELECT 1 FROM user_profiles WHERE id <> p_user_id) THEN
    RAISE EXCEPTION 'This installation already has users' USING ERRCODE = '55000';
  END IF;

  SELECT id INTO v_role FROM roles WHERE name = 'Superadmin' AND is_system_role LIMIT 1;
  IF v_role IS NULL THEN
    RAISE EXCEPTION 'The Superadmin role is missing' USING ERRCODE = '55000';
  END IF;

  INSERT INTO user_profiles (id, email, name, phone, is_superadmin, is_active, has_completed_onboarding)
  VALUES (p_user_id, p_email, p_name, p_phone, true, true, true)
  ON CONFLICT (id) DO UPDATE
     SET email = EXCLUDED.email,
         name = EXCLUDED.name,
         phone = EXCLUDED.phone,
         is_superadmin = true,
         is_active = true,
         has_completed_onboarding = true;

  INSERT INTO user_roles (user_id, role_id, assigned_by)
  VALUES (p_user_id, v_role, p_user_id)
  ON CONFLICT (user_id, role_id) DO NOTHING;

  UPDATE app_settings SET registered_by = p_user_id, updated_at = now() WHERE id = true;
END
$$;

-- FUNCTION: enforce_client_visibility()
CREATE FUNCTION project.enforce_client_visibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  IF project.caller_is_trusted() THEN
    RETURN NEW;
  END IF;
  IF (TG_OP = 'INSERT' AND NEW.client_visible)
     OR (TG_OP = 'UPDATE' AND NEW.client_visible IS DISTINCT FROM OLD.client_visible) THEN
    IF NOT project.user_can_manage_project(NEW.project_id) THEN
      RAISE EXCEPTION 'Only a project manager can change what the client can see' USING ERRCODE = '42501';
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.project_id IS DISTINCT FROM OLD.project_id THEN
    RAISE EXCEPTION 'The project cannot be changed' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: enforce_deliverable_rules()
CREATE FUNCTION project.enforce_deliverable_rules() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  IF NEW.file_id IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.file_id IS DISTINCT FROM OLD.file_id)
     AND NOT EXISTS (SELECT 1 FROM project.project_files f WHERE f.id = NEW.file_id AND f.project_id = NEW.project_id) THEN
    RAISE EXCEPTION 'The attached file must belong to the same project' USING ERRCODE = '23514';
  END IF;
  IF project.caller_is_trusted() THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.submitted_by := project.current_user_id();
    IF NOT project.user_can_manage_project(NEW.project_id) THEN
      IF NEW.status NOT IN ('draft', 'pending_review') THEN
        RAISE EXCEPTION 'New deliverables start as a draft or pending review' USING ERRCODE = '42501';
      END IF;
      IF NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL OR NEW.shared_at IS NOT NULL OR NEW.shared_by IS NOT NULL THEN
        RAISE EXCEPTION 'Approval and client sharing are done by a project manager' USING ERRCODE = '42501';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE
  IF NEW.project_id IS DISTINCT FROM OLD.project_id THEN
    RAISE EXCEPTION 'The project cannot be changed' USING ERRCODE = '42501';
  END IF;
  IF NOT project.user_can_manage_project(OLD.project_id) THEN
    IF NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
       OR NEW.shared_at IS DISTINCT FROM OLD.shared_at OR NEW.shared_by IS DISTINCT FROM OLD.shared_by
       OR NEW.feedback IS DISTINCT FROM OLD.feedback OR NEW.submitted_by IS DISTINCT FROM OLD.submitted_by THEN
      RAISE EXCEPTION 'Approval, sharing and feedback are recorded by a project manager or the client' USING ERRCODE = '42501';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status
       AND NOT (NEW.status = 'pending_review' AND OLD.status IN ('draft', 'rejected', 'revised'))
       AND NOT (NEW.status = 'revised' AND OLD.status = 'rejected') THEN
      RAISE EXCEPTION 'You can only submit a deliverable for review. Sharing, returning and approving are done by a project manager.'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: enforce_dependencies_before_start()
CREATE FUNCTION project.enforce_dependencies_before_start() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE
  v_waiting text;
BEGIN
  IF NEW.status IS DISTINCT FROM 'in_progress' OR OLD.status IS NOT DISTINCT FROM 'in_progress' THEN
    RETURN NEW;
  END IF;
  IF project.caller_is_trusted() OR project.user_is_superadmin() OR project.user_can_manage_project(NEW.project_id) THEN
    RETURN NEW;
  END IF;

  SELECT string_agg(p.name, ', ' ORDER BY p.name) INTO v_waiting
  FROM project.task_dependencies td
  JOIN project.tasks p ON p.id = td.depends_on_task_id
  WHERE td.task_id = NEW.id AND p.status IS DISTINCT FROM 'done';

  IF v_waiting IS NOT NULL THEN
    RAISE EXCEPTION 'Waiting for: %', v_waiting USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: enforce_project_file_rules()
CREATE FUNCTION project.enforce_project_file_rules() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  IF project.caller_is_trusted() THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'Files must be uploaded through the application' USING ERRCODE = '42501';
  END IF;
  IF NEW.project_id   IS DISTINCT FROM OLD.project_id
  OR NEW.storage_path IS DISTINCT FROM OLD.storage_path
  OR NEW.uploaded_by  IS DISTINCT FROM OLD.uploaded_by
  OR NEW.size_bytes   IS DISTINCT FROM OLD.size_bytes
  OR NEW.mime_type    IS DISTINCT FROM OLD.mime_type
  OR NEW.task_id      IS DISTINCT FROM OLD.task_id
  OR NEW.created_at   IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Only the file name can be changed' USING ERRCODE = '42501';
  END IF;
  IF NEW.client_visible IS DISTINCT FROM OLD.client_visible AND NOT project.user_can_manage_project(OLD.project_id) THEN
    RAISE EXCEPTION 'Only a project manager can share files with the client' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: enforce_role_assignment_rules()
CREATE FUNCTION project.enforce_role_assignment_rules() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE
  v_target uuid := COALESCE(NEW.user_id, OLD.user_id);
  v_role   record;
  v_role_id uuid;
BEGIN
  IF project.caller_is_trusted() OR project.user_is_superadmin() THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF v_target = project.current_user_id() OR (TG_OP = 'UPDATE' AND OLD.user_id = project.current_user_id()) THEN
    RAISE EXCEPTION 'You cannot change your own roles' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (SELECT 1 FROM project.user_profiles WHERE id = v_target AND is_superadmin) THEN
    RAISE EXCEPTION 'Only a superadmin can change a superadmin''s roles' USING ERRCODE = '42501';
  END IF;

  FOREACH v_role_id IN ARRAY ARRAY[
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.role_id END,
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.role_id END
  ] LOOP
    CONTINUE WHEN v_role_id IS NULL;
    SELECT name, is_system_role, permissions INTO v_role FROM project.roles WHERE id = v_role_id;
    IF NOT FOUND THEN CONTINUE; END IF;
    IF v_role.is_system_role THEN
      RAISE EXCEPTION 'Only a superadmin can assign or remove the % role', v_role.name USING ERRCODE = '42501';
    END IF;
    IF NOT project.caller_holds_permissions(v_role.permissions) THEN
      RAISE EXCEPTION 'You can only assign or remove roles whose permissions you hold yourself (%)', v_role.name USING ERRCODE = '42501';
    END IF;
  END LOOP;

  RETURN COALESCE(NEW, OLD);
END;
$$;

-- FUNCTION: enforce_role_definition_rules()
CREATE FUNCTION project.enforce_role_definition_rules() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  IF project.caller_is_trusted() OR project.user_is_superadmin() THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF (TG_OP IN ('UPDATE', 'DELETE') AND OLD.is_system_role) OR (TG_OP IN ('INSERT', 'UPDATE') AND NEW.is_system_role) THEN
    RAISE EXCEPTION 'Only a superadmin can change system roles' USING ERRCODE = '42501';
  END IF;

  IF TG_OP IN ('INSERT', 'UPDATE') AND NOT project.caller_holds_permissions(NEW.permissions) THEN
    RAISE EXCEPTION 'You can''t give a role a permission you don''t hold yourself' USING ERRCODE = '42501';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;

-- FUNCTION: enforce_task_field_rules()
CREATE FUNCTION project.enforce_task_field_rules() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE
  is_manager boolean;
  is_creator boolean;
BEGIN
  IF project.caller_is_trusted() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.created_by := project.current_user_id();
    is_manager := project.user_can_manage_project(NEW.project_id);
    IF NEW.assigned_to IS NOT NULL AND NOT project.user_is_valid_task_member(NEW.project_id, NEW.assigned_to) THEN
      RAISE EXCEPTION 'Assignee must be an active internal member of this project team' USING ERRCODE = '23514';
    END IF;
    IF NEW.reviewer_id IS NOT NULL THEN
      IF NOT is_manager THEN
        RAISE EXCEPTION 'Only a project manager can choose the reviewer' USING ERRCODE = '42501';
      END IF;
      IF NOT project.user_is_valid_task_member(NEW.project_id, NEW.reviewer_id) THEN
        RAISE EXCEPTION 'Reviewer must be an active internal member of this project team' USING ERRCODE = '23514';
      END IF;
      IF NEW.reviewer_id = NEW.assigned_to THEN
        RAISE EXCEPTION 'The reviewer cannot be the person assigned to the task' USING ERRCODE = '23514';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE
  IF NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'The task creator cannot be changed' USING ERRCODE = '42501';
  END IF;

  is_manager := project.user_can_manage_project(OLD.project_id);
  IF NOT is_manager THEN
    is_creator := OLD.created_by IS NOT DISTINCT FROM project.current_user_id();

    IF NEW.project_id IS DISTINCT FROM OLD.project_id THEN
      RAISE EXCEPTION 'Only a project manager can move a task to another project' USING ERRCODE = '42501';
    END IF;

    IF NOT is_creator AND (
         NEW.name            IS DISTINCT FROM OLD.name
      OR NEW.priority        IS DISTINCT FROM OLD.priority
      OR NEW.start_date      IS DISTINCT FROM OLD.start_date
      OR NEW.due_date        IS DISTINCT FROM OLD.due_date
      OR NEW.estimated_hours IS DISTINCT FROM OLD.estimated_hours
      OR NEW.parent_task_id  IS DISTINCT FROM OLD.parent_task_id) THEN
      RAISE EXCEPTION 'Only the task creator or a project manager can change the title, priority, dates or estimate'
        USING ERRCODE = '42501';
    END IF;

    IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to AND NOT is_creator
       AND NOT (OLD.assigned_to IS NULL AND NEW.assigned_to = project.current_user_id()) THEN
      RAISE EXCEPTION 'Only the task creator or a project manager can reassign this task' USING ERRCODE = '42501';
    END IF;

    IF NEW.reviewer_id IS DISTINCT FROM OLD.reviewer_id THEN
      RAISE EXCEPTION 'Only a project manager can choose the reviewer' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to AND NEW.assigned_to IS NOT NULL
     AND NOT project.user_is_valid_task_member(NEW.project_id, NEW.assigned_to) THEN
    RAISE EXCEPTION 'Assignee must be an active internal member of this project team' USING ERRCODE = '23514';
  END IF;
  IF NEW.reviewer_id IS DISTINCT FROM OLD.reviewer_id AND NEW.reviewer_id IS NOT NULL
     AND NOT project.user_is_valid_task_member(NEW.project_id, NEW.reviewer_id) THEN
    RAISE EXCEPTION 'Reviewer must be an active internal member of this project team' USING ERRCODE = '23514';
  END IF;
  IF NEW.reviewer_id IS NOT NULL AND NEW.reviewer_id = NEW.assigned_to
     AND (NEW.reviewer_id IS DISTINCT FROM OLD.reviewer_id OR NEW.assigned_to IS DISTINCT FROM OLD.assigned_to) THEN
    RAISE EXCEPTION 'The reviewer cannot be the person assigned to the task' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: enforce_task_status_transition()
CREATE FUNCTION project.enforce_task_status_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE privileged boolean;
BEGIN
  privileged := project.current_user_id() IS NULL
    OR COALESCE(project.request_role(), '') = 'service_role'
    OR project.user_can_manage_project(NEW.project_id)
    OR (TG_OP = 'UPDATE' AND OLD.reviewer_id IS NOT NULL AND OLD.reviewer_id = project.current_user_id()
        AND OLD.assigned_to IS DISTINCT FROM project.current_user_id());

  IF TG_OP = 'INSERT' THEN
    IF NEW.status IN ('done','changes_requested','review') AND NOT privileged THEN
      NEW.status := 'todo';
    END IF;
  ELSE
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
    IF (NEW.status IN ('done','changes_requested') OR OLD.status = 'done') AND NOT privileged THEN
      RAISE EXCEPTION 'Only the reviewer or a project manager can approve, request changes or reopen this task'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.status = 'changes_requested' AND COALESCE(btrim(NEW.review_note), '') = '' THEN
      RAISE EXCEPTION 'A note is required when requesting changes' USING ERRCODE = '23514';
    END IF;
    IF OLD.status = 'done' AND NEW.status <> 'done' THEN NEW.completed_at := NULL; END IF;
  END IF;

  IF NEW.status = 'in_progress' AND NEW.started_at IS NULL THEN NEW.started_at := now(); END IF;
  IF NEW.status = 'done' THEN
    NEW.completed_at := COALESCE(NEW.completed_at, now());
    NEW.progress_percent := 100;
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: enforce_timesheet_lock()
CREATE FUNCTION project.enforce_timesheet_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  IF project.current_user_id() IS NULL OR COALESCE(project.request_role(), '') = 'service_role' OR project.user_is_superadmin() THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  IF TG_OP IN ('UPDATE','DELETE') AND EXISTS (
      SELECT 1 FROM project.timesheets t
      WHERE t.user_id = OLD.user_id AND t.week_start_date = OLD.week_start_date AND t.status IN ('submitted','approved')) THEN
    RAISE EXCEPTION 'This week''s timesheet has been submitted and is locked' USING ERRCODE = '55006';
  END IF;
  IF TG_OP IN ('INSERT','UPDATE') AND EXISTS (
      SELECT 1 FROM project.timesheets t
      WHERE t.user_id = NEW.user_id AND t.week_start_date = NEW.week_start_date AND t.status IN ('submitted','approved')) THEN
    RAISE EXCEPTION 'This week''s timesheet has been submitted and is locked' USING ERRCODE = '55006';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;

-- FUNCTION: enforce_timesheet_rules()
CREATE FUNCTION project.enforce_timesheet_rules() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE is_approver boolean;
BEGIN
  IF project.caller_is_trusted() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.user_id IS DISTINCT FROM project.current_user_id() THEN
      RAISE EXCEPTION 'You can only create your own timesheet' USING ERRCODE = '42501';
    END IF;
    IF NEW.status NOT IN ('draft', 'submitted') THEN
      RAISE EXCEPTION 'A new timesheet can only be a draft or submitted' USING ERRCODE = '42501';
    END IF;
    IF NEW.reviewed_by IS NOT NULL OR NEW.reviewed_at IS NOT NULL OR NEW.review_note IS NOT NULL THEN
      RAISE EXCEPTION 'Review fields are set by the approver' USING ERRCODE = '42501';
    END IF;
    IF NEW.status = 'submitted' THEN NEW.submitted_at := COALESCE(NEW.submitted_at, now()); END IF;
    RETURN NEW;
  END IF;

  IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.week_start_date IS DISTINCT FROM OLD.week_start_date THEN
    RAISE EXCEPTION 'A timesheet''s owner and week cannot be changed' USING ERRCODE = '42501';
  END IF;

  is_approver := project.user_can_approve_timesheet_of(OLD.user_id);  -- always false for one's own timesheet

  IF is_approver THEN
    IF NEW.total_hours IS DISTINCT FROM OLD.total_hours OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at THEN
      RAISE EXCEPTION 'Approvers cannot change the submitted hours' USING ERRCODE = '42501';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      IF NEW.status IN ('approved', 'rejected') AND OLD.status <> 'submitted' THEN
        RAISE EXCEPTION 'Only a submitted timesheet can be approved or rejected' USING ERRCODE = '23514';
      END IF;
      IF NEW.status = 'submitted' THEN
        RAISE EXCEPTION 'Only the employee can submit a timesheet' USING ERRCODE = '42501';
      END IF;
      NEW.reviewed_by := project.current_user_id();
      NEW.reviewed_at := now();
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.user_id = project.current_user_id() THEN
    IF NEW.reviewed_by IS DISTINCT FROM OLD.reviewed_by OR NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at
       OR NEW.review_note IS DISTINCT FROM OLD.review_note THEN
      RAISE EXCEPTION 'Review fields are set by the approver' USING ERRCODE = '42501';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      IF NOT (OLD.status IN ('draft', 'rejected') AND NEW.status = 'submitted') THEN
        RAISE EXCEPTION 'You can only submit your timesheet. Approving, rejecting and reopening are done by an approver.'
          USING ERRCODE = '42501';
      END IF;
      NEW.submitted_at := now();
    ELSIF OLD.status IN ('submitted', 'approved') THEN
      RAISE EXCEPTION 'This timesheet has been submitted and is locked' USING ERRCODE = '55006';
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Not allowed to change this timesheet' USING ERRCODE = '42501';
END;
$$;

-- FUNCTION: get_project_stakeholders(uuid)
CREATE FUNCTION project.get_project_stakeholders(project_uuid uuid) RETURNS TABLE(id uuid, user_id uuid, role text, user_name text, user_email text, user_image text, added_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        ps.id,
        ps.user_id,
        ps.role,
        up.name AS user_name,
        up.email AS user_email,
        up.image AS user_image,
        ps.added_at
    FROM project.project_stakeholders ps
    LEFT JOIN project.user_profiles up ON ps.user_id = up.id
    WHERE ps.project_id = project_uuid
    ORDER BY ps.added_at DESC;
END;
$$;

-- COMMENT: FUNCTION get_project_stakeholders(project_uuid uuid)
COMMENT ON FUNCTION project.get_project_stakeholders(project_uuid uuid) IS 'Returns all stakeholders for a project with their user profile information. Uses SECURITY DEFINER to bypass RLS.';

-- FUNCTION: get_week_start_date(date)
CREATE FUNCTION project.get_week_start_date(input_date date) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  -- ISO 8601: Monday = 1, Sunday = 7
  -- Subtract days to get to Monday
  RETURN input_date - (EXTRACT(ISODOW FROM input_date)::INTEGER - 1);
END;
$$;

-- COMMENT: FUNCTION get_week_start_date(input_date date)
COMMENT ON FUNCTION project.get_week_start_date(input_date date) IS 'Returns Monday of the week for a given date using ISO 8601 standard (Monday = week start).';

-- FUNCTION: is_superadmin(uuid)
CREATE FUNCTION project.is_superadmin(user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  -- Check is_superadmin flag
  IF EXISTS (
    SELECT 1 FROM project.user_profiles
    WHERE id = is_superadmin.user_id
    AND is_superadmin = TRUE
  ) THEN
    RETURN TRUE;
  END IF;

  -- Check for Superadmin role
  RETURN EXISTS (
    SELECT 1
    FROM project.user_roles ur
    JOIN project.roles r ON ur.role_id = r.id
    WHERE ur.user_id = is_superadmin.user_id
    AND r.is_system_role = TRUE
    AND LOWER(r.name) = 'superadmin'
  );
END;
$$;

-- COMMENT: FUNCTION is_superadmin(user_id uuid)
COMMENT ON FUNCTION project.is_superadmin(user_id uuid) IS 'Checks if a specific user is a superadmin. Backwards compatibility wrapper.';

-- FUNCTION: log_task_activity()
CREATE FUNCTION project.log_task_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE act text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO project.task_activity (task_id, project_id, actor_id, action, to_value)
    VALUES (NEW.id, NEW.project_id, project.current_user_id(), 'created', NEW.status);
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    act := CASE
      WHEN NEW.status = 'review' THEN 'review_submitted'
      WHEN NEW.status = 'done' THEN 'review_approved'
      WHEN NEW.status = 'changes_requested' THEN 'changes_requested'
      WHEN OLD.status = 'done' THEN 'reopened'
      ELSE 'status_changed' END;
    INSERT INTO project.task_activity (task_id, project_id, actor_id, action, from_value, to_value, note)
    VALUES (NEW.id, NEW.project_id, project.current_user_id(), act, OLD.status, NEW.status,
            CASE WHEN act IN ('review_submitted','review_approved','changes_requested','reopened') THEN NEW.review_note END);
  END IF;
  IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to THEN
    INSERT INTO project.task_activity (task_id, project_id, actor_id, action, from_value, to_value)
    VALUES (NEW.id, NEW.project_id, project.current_user_id(), 'assigned', OLD.assigned_to::text, NEW.assigned_to::text);
  END IF;
  IF NEW.priority IS DISTINCT FROM OLD.priority THEN
    INSERT INTO project.task_activity (task_id, project_id, actor_id, action, from_value, to_value)
    VALUES (NEW.id, NEW.project_id, project.current_user_id(), 'priority_changed', OLD.priority, NEW.priority);
  END IF;
  IF NEW.progress_percent IS DISTINCT FROM OLD.progress_percent AND NEW.status <> 'done' THEN
    INSERT INTO project.task_activity (task_id, project_id, actor_id, action, from_value, to_value)
    VALUES (NEW.id, NEW.project_id, project.current_user_id(), 'progress_updated', OLD.progress_percent::text, NEW.progress_percent::text);
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: notify_client_project_status()
CREATE FUNCTION project.notify_client_project_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE
  v_label text;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status OR NOT COALESCE(NEW.shared_with_client, false) OR NEW.archived_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  v_label := initcap(replace(NEW.status, '_', ' '));
  INSERT INTO project.notifications (user_id, title, message, type, link, project_id, dedupe_key)
  SELECT up.id, 'Project status updated', format('%s is now: %s', NEW.name, v_label), 'project_status',
         '/client-portal/projects/' || NEW.id::text, NEW.id,
         'pstatus:' || NEW.id::text || ':' || NEW.status || ':' || COALESCE(NEW.updated_at, now())::text
  FROM project.user_profiles up
  WHERE up.is_client AND up.client_account_id = NEW.account_id AND up.is_active IS DISTINCT FROM false
  ON CONFLICT (user_id, dedupe_key) WHERE dedupe_key IS NOT NULL DO NOTHING;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'notify_client_project_status failed: %', SQLERRM;
  RETURN NEW;
END;
$$;

-- FUNCTION: notify_workflow_step_active()
CREATE FUNCTION project.notify_workflow_step_active() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE
  v_inst        record;
  v_node        record;
  v_project     record;
  v_is_client   boolean;
  v_recipients  uuid[] := '{}';
  v_title       text;
  v_msg         text;
  v_link        text;
  v_type        text;
  v_key         text;
BEGIN
  -- Only when a step becomes active (new, re-activated) or gets a new assignee while active
  IF NEW.status IS DISTINCT FROM 'active' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'active'
     AND OLD.assigned_user_id IS NOT DISTINCT FROM NEW.assigned_user_id THEN
    RETURN NEW;
  END IF;

  SELECT project_id, task_id INTO v_inst FROM project.workflow_instances WHERE id = NEW.workflow_instance_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  SELECT id, node_type, label, entity_id, settings INTO v_node FROM project.workflow_nodes WHERE id = NEW.node_id;
  IF NOT FOUND OR v_node.node_type IN ('start', 'end', 'conditional', 'sync') THEN RETURN NEW; END IF;

  IF v_inst.project_id IS NOT NULL THEN
    SELECT id, name, account_id, shared_with_client INTO v_project FROM project.projects WHERE id = v_inst.project_id;
  END IF;

  v_is_client := v_node.node_type = 'client' OR COALESCE(v_node.settings->>'client_approval', '') = 'true';
  v_key := 'wfstep:' || NEW.id::text || ':' || COALESCE(NEW.assigned_user_id::text, '-') || ':' || COALESCE(NEW.activated_at, now())::text;

  IF v_is_client THEN
    -- Client-approval step: tell the client users of the project's account (only if the project is shared)
    IF v_project.id IS NOT NULL AND v_project.shared_with_client THEN
      SELECT COALESCE(array_agg(up.id), '{}') INTO v_recipients
      FROM project.user_profiles up
      WHERE up.is_client AND up.client_account_id = v_project.account_id AND up.is_active IS DISTINCT FROM false;
    END IF;
    v_type := 'approval_request';
    v_title := 'Your approval is needed';
    v_msg := format('"%s" on %s is waiting for your approval', v_node.label, v_project.name);
    v_link := '/client-portal/approvals';
  ELSE
    -- Internal step: the assignee, people assigned to this node, otherwise holders of the role /
    -- members of the department (through a role in it, or added directly)
    IF NEW.assigned_user_id IS NOT NULL THEN
      v_recipients := ARRAY[NEW.assigned_user_id];
    ELSE
      SELECT COALESCE(array_agg(DISTINCT x.uid), '{}') INTO v_recipients FROM (
        SELECT na.user_id AS uid FROM project.workflow_node_assignments na
          WHERE na.workflow_instance_id = NEW.workflow_instance_id AND na.node_id = NEW.node_id
        UNION
        SELECT ur.user_id FROM project.user_roles ur
          WHERE v_node.node_type IN ('role', 'approval') AND v_node.entity_id IS NOT NULL AND ur.role_id = v_node.entity_id
        UNION
        SELECT ur.user_id FROM project.user_roles ur JOIN project.roles r ON r.id = ur.role_id
          WHERE v_node.node_type = 'department' AND v_node.entity_id IS NOT NULL AND r.department_id = v_node.entity_id
        UNION
        SELECT dm.user_id FROM project.department_members dm
          WHERE v_node.node_type = 'department' AND v_node.entity_id IS NOT NULL AND dm.department_id = v_node.entity_id
      ) x;
    END IF;
    -- Never notify clients or deactivated users through an internal step
    SELECT COALESCE(array_agg(up.id), '{}') INTO v_recipients
    FROM project.user_profiles up
    WHERE up.id = ANY (v_recipients) AND NOT COALESCE(up.is_client, false) AND up.is_active IS DISTINCT FROM false;

    v_type := CASE WHEN v_node.node_type = 'approval' THEN 'approval_request' ELSE 'workflow_step' END;
    v_title := CASE WHEN v_node.node_type = 'approval' THEN 'Approval needed' ELSE 'Workflow step assigned' END;
    v_msg := CASE WHEN v_project.name IS NOT NULL
                  THEN format('"%s" on %s is waiting for you', v_node.label, v_project.name)
                  ELSE format('"%s" is waiting for you', v_node.label) END;
    v_link := CASE WHEN v_inst.project_id IS NOT NULL THEN '/projects/' || v_inst.project_id::text ELSE '/dashboard' END;
  END IF;

  IF COALESCE(array_length(v_recipients, 1), 0) = 0 THEN RETURN NEW; END IF;

  INSERT INTO project.notifications (user_id, title, message, type, link, project_id, dedupe_key)
  SELECT u, v_title, v_msg, v_type, v_link, v_inst.project_id, v_key FROM unnest(v_recipients) AS u
  ON CONFLICT (user_id, dedupe_key) WHERE dedupe_key IS NOT NULL DO NOTHING;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- A notification problem must never block the workflow
  RAISE WARNING 'notify_workflow_step_active failed: %', SQLERRM;
  RETURN NEW;
END;
$$;

-- FUNCTION: prepare_comment()
CREATE FUNCTION project.prepare_comment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE parent_row project.comments%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    NEW.updated_at := now();
    NEW.project_id := OLD.project_id; NEW.task_id := OLD.task_id; NEW.update_id := OLD.update_id; NEW.parent_id := OLD.parent_id;
    RETURN NEW;
  END IF;
  IF NEW.task_id IS NOT NULL THEN
    SELECT project_id INTO NEW.project_id FROM project.tasks WHERE id = NEW.task_id;
  ELSE
    SELECT project_id INTO NEW.project_id FROM project.project_updates WHERE id = NEW.update_id;
  END IF;
  IF NEW.project_id IS NULL THEN RAISE EXCEPTION 'Comment target not found' USING ERRCODE = '23503'; END IF;
  IF NEW.parent_id IS NOT NULL THEN
    SELECT * INTO parent_row FROM project.comments WHERE id = NEW.parent_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Parent comment not found' USING ERRCODE = '23503'; END IF;
    IF parent_row.parent_id IS NOT NULL THEN RAISE EXCEPTION 'Replies can only be one level deep' USING ERRCODE = '23514'; END IF;
    IF parent_row.task_id IS DISTINCT FROM NEW.task_id OR parent_row.update_id IS DISTINCT FROM NEW.update_id THEN
      RAISE EXCEPTION 'Reply must belong to the same thread' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: protect_profile_privileged_columns()
CREATE FUNCTION project.protect_profile_privileged_columns() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  -- service role / direct SQL (no JWT user) and superadmins may change anything
  IF project.current_user_id() IS NULL OR COALESCE(project.request_role(), '') = 'service_role' OR project.user_is_superadmin() THEN
    RETURN NEW;
  END IF;
  IF NEW.is_superadmin     IS DISTINCT FROM OLD.is_superadmin
  OR NEW.is_client         IS DISTINCT FROM OLD.is_client
  OR NEW.client_account_id IS DISTINCT FROM OLD.client_account_id
  OR NEW.email             IS DISTINCT FROM OLD.email
  OR NEW.is_active         IS DISTINCT FROM OLD.is_active
  OR NEW.deactivated_at    IS DISTINCT FROM OLD.deactivated_at
  OR NEW.suspended_until   IS DISTINCT FROM OLD.suspended_until
  OR NEW.suspension_reason IS DISTINCT FROM OLD.suspension_reason THEN
    RAISE EXCEPTION 'Not allowed to change privileged profile fields' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

