-- COMMENT: FUNCTION update_updated_at_column()
COMMENT ON FUNCTION project.update_updated_at_column() IS 'Automatically updates the updated_at column to NOW() when a row is modified.';

-- FUNCTION: user_can_access_project(uuid)
CREATE FUNCTION project.user_can_access_project(check_project_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE
  proj_account_id uuid;
BEGIN
  -- Get the project's account_id
  SELECT account_id INTO proj_account_id
  FROM project.projects
  WHERE id = check_project_id;

  -- Check access: assigned, creator, or account manager
  RETURN (
    user_is_project_assigned(check_project_id)
    OR user_is_project_creator(check_project_id)
    OR (proj_account_id IS NOT NULL AND user_is_account_manager(proj_account_id))
  );
END;
$$;

-- COMMENT: FUNCTION user_can_access_project(check_project_id uuid)
COMMENT ON FUNCTION project.user_can_access_project(check_project_id uuid) IS 'Checks if the current user can access a specific project (assigned, creator, or account manager). Uses SECURITY DEFINER to bypass RLS.';

-- FUNCTION: user_can_approve_timesheet_of(uuid)
CREATE FUNCTION project.user_can_approve_timesheet_of(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
  SELECT uid IS NOT NULL AND uid <> project.current_user_id() AND NOT project.user_is_client() AND (
       project.user_is_superadmin()
    OR project.user_has_permission('view_all_time_entries')
    OR (project.user_has_permission('approve_timesheets') AND EXISTS (
          SELECT 1 FROM project.time_entries te
          WHERE te.user_id = uid AND project.user_can_contribute(te.project_id)))
  );
$$;

-- FUNCTION: user_can_contribute(uuid)
CREATE FUNCTION project.user_can_contribute(pid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
  SELECT pid IS NOT NULL AND NOT project.user_is_client()
    AND NOT EXISTS (SELECT 1 FROM project.projects ap WHERE ap.id = pid AND ap.archived_at IS NOT NULL)
    AND (
         project.user_is_superadmin()
      OR project.user_has_permission('manage_all_projects')
      OR project.user_can_access_project(pid)
      OR EXISTS (SELECT 1 FROM project.projects p WHERE p.id = pid AND p.assigned_user_id = project.current_user_id())
      OR EXISTS (SELECT 1 FROM project.tasks t WHERE t.project_id = pid AND t.assigned_to = project.current_user_id())
    );
$$;

-- FUNCTION: user_can_manage_project(uuid)
CREATE FUNCTION project.user_can_manage_project(pid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
  SELECT pid IS NOT NULL AND NOT project.user_is_client() AND (
       project.user_is_superadmin()
    OR project.user_has_permission('manage_all_projects')
    OR (project.user_has_permission('manage_projects') AND project.user_can_contribute(pid))
  );
$$;

-- FUNCTION: user_can_manage_workflow(uuid)
CREATE FUNCTION project.user_can_manage_workflow(workflow_instance_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1
    FROM workflow_instances wi
    LEFT JOIN project_assignments pa ON pa.project_id = wi.project_id AND pa.removed_at IS NULL
    LEFT JOIN projects p ON p.id = wi.project_id
    WHERE wi.id = user_can_manage_workflow.workflow_instance_id
    AND (
      user_is_superadmin()
      OR user_has_permission('manage_all_workflows')
      OR (
        user_has_permission('execute_workflows')
        AND pa.user_id = project.current_user_id()
        AND pa.removed_at IS NULL
      )
    )
  );
END;
$$;

-- COMMENT: FUNCTION user_can_manage_workflow(workflow_instance_id uuid)
COMMENT ON FUNCTION project.user_can_manage_workflow(workflow_instance_id uuid) IS 'Checks if the current user can manage a specific workflow instance.';

-- FUNCTION: user_can_start_project_workflow(uuid)
CREATE FUNCTION project.user_can_start_project_workflow(check_project_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  RETURN EXISTS (
    -- Check project_assignments table
    SELECT 1 FROM project.project_assignments
    WHERE project_id = check_project_id
    AND user_id = project.current_user_id()
    AND removed_at IS NULL
  )
  OR EXISTS (
    -- Check if user is project creator or assigned user
    SELECT 1 FROM project.projects
    WHERE id = check_project_id
    AND (created_by = project.current_user_id() OR assigned_user_id = project.current_user_id())
  );
END;
$$;

-- COMMENT: FUNCTION user_can_start_project_workflow(check_project_id uuid)
COMMENT ON FUNCTION project.user_can_start_project_workflow(check_project_id uuid) IS 'Checks if the current user can start a workflow on a project. Returns true if user is assigned to the project, or is the project creator/assignee. Uses SECURITY DEFINER to bypass RLS.';

-- FUNCTION: user_can_view_project(uuid)
CREATE FUNCTION project.user_can_view_project(pid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
  SELECT pid IS NOT NULL AND NOT project.user_is_client() AND (
       project.user_is_superadmin()
    OR project.user_has_permission('view_all_projects')
    OR project.user_has_permission('manage_all_projects')
    OR project.user_can_access_project(pid)
    OR EXISTS (SELECT 1 FROM project.projects p WHERE p.id = pid AND p.assigned_user_id = project.current_user_id())
    OR EXISTS (SELECT 1 FROM project.tasks t WHERE t.project_id = pid AND t.assigned_to = project.current_user_id())
  );
$$;

-- FUNCTION: user_can_view_workflow(uuid)
CREATE FUNCTION project.user_can_view_workflow(workflow_instance_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  -- Single query, bypasses nested RLS via SECURITY DEFINER
  RETURN EXISTS (
    SELECT 1
    FROM workflow_instances wi
    LEFT JOIN project_assignments pa ON pa.project_id = wi.project_id AND pa.removed_at IS NULL
    LEFT JOIN projects p ON p.id = wi.project_id
    LEFT JOIN tasks t ON t.id = wi.task_id
    WHERE wi.id = user_can_view_workflow.workflow_instance_id
    AND (
      user_is_superadmin()
      OR user_has_permission('view_all_workflows')
      OR (pa.user_id = project.current_user_id() AND pa.removed_at IS NULL)
      OR t.assigned_to = project.current_user_id()
      OR p.created_by = project.current_user_id()
      OR p.assigned_user_id = project.current_user_id()
    )
  );
END;
$$;

-- COMMENT: FUNCTION user_can_view_workflow(workflow_instance_id uuid)
COMMENT ON FUNCTION project.user_can_view_workflow(workflow_instance_id uuid) IS 'Checks if the current user can view a specific workflow instance. Uses SECURITY DEFINER to prevent nested RLS performance issues.';

-- FUNCTION: user_can_view_workflow_row(uuid, uuid)
CREATE FUNCTION project.user_can_view_workflow_row(p_project_id uuid, p_task_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
  SELECT (p_project_id IS NOT NULL AND project.user_can_start_project_workflow(p_project_id))
      OR (p_task_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM project.tasks t WHERE t.id = p_task_id AND t.assigned_to = project.current_user_id()));
$$;

-- COMMENT: FUNCTION user_can_view_workflow_row(p_project_id uuid, p_task_id uuid)
COMMENT ON FUNCTION project.user_can_view_workflow_row(p_project_id uuid, p_task_id uuid) IS 'Row-based workflow visibility (team member, project creator/manager, task assignee). Used by the workflow_instances SELECT policy so a new instance is visible to its creator within the inserting statement.';

-- FUNCTION: user_has_permission(text)
CREATE FUNCTION project.user_has_permission(permission_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  -- Check if user has permission via their roles
  -- Runs with creator privileges (SECURITY DEFINER), bypassing RLS
  RETURN EXISTS (
    SELECT 1
    FROM project.user_roles ur
    JOIN project.roles r ON ur.role_id = r.id
    WHERE ur.user_id = project.current_user_id()
    AND (r.permissions->permission_name)::boolean = TRUE
  );
END;
$$;

-- COMMENT: FUNCTION user_has_permission(permission_name text)
COMMENT ON FUNCTION project.user_has_permission(permission_name text) IS 'Checks if the current user has a specific permission. Uses SECURITY DEFINER to bypass RLS and prevent circular dependency.';

-- FUNCTION: user_is_account_manager(uuid)
CREATE FUNCTION project.user_is_account_manager(check_account_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM project.accounts
    WHERE id = check_account_id
    AND account_manager_id = project.current_user_id()
  );
END;
$$;

-- COMMENT: FUNCTION user_is_account_manager(check_account_id uuid)
COMMENT ON FUNCTION project.user_is_account_manager(check_account_id uuid) IS 'Checks if the current user is the account manager for a specific account. Uses SECURITY DEFINER to bypass RLS and prevent circular dependency.';

-- FUNCTION: user_is_account_member(uuid)
CREATE FUNCTION project.user_is_account_member(check_account_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM project.account_members
    WHERE account_id = check_account_id
    AND user_id = project.current_user_id()
  );
END;
$$;

-- COMMENT: FUNCTION user_is_account_member(check_account_id uuid)
COMMENT ON FUNCTION project.user_is_account_member(check_account_id uuid) IS 'Checks if the current user is a member of a specific account. Uses SECURITY DEFINER to bypass RLS and prevent circular dependency.';

-- FUNCTION: user_is_client()
CREATE FUNCTION project.user_is_client() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
  SELECT COALESCE((SELECT is_client FROM project.user_profiles WHERE id = project.current_user_id()), false);
$$;

-- FUNCTION: user_is_client_for_account(uuid)
CREATE FUNCTION project.user_is_client_for_account(check_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM project.user_profiles
    WHERE id = project.current_user_id()
    AND is_client = true
    AND client_account_id = check_account_id
  );
$$;

-- FUNCTION: user_is_client_for_project(uuid)
CREATE FUNCTION project.user_is_client_for_project(check_project_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM project.projects p
    JOIN project.user_profiles up ON up.client_account_id = p.account_id
    WHERE p.id = check_project_id
    AND up.id = project.current_user_id()
    AND up.is_client = true
  );
$$;

-- FUNCTION: user_is_project_assigned(uuid)
CREATE FUNCTION project.user_is_project_assigned(check_project_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM project.project_assignments
    WHERE project_id = check_project_id
    AND user_id = project.current_user_id()
    AND removed_at IS NULL
  );
END;
$$;

-- COMMENT: FUNCTION user_is_project_assigned(check_project_id uuid)
COMMENT ON FUNCTION project.user_is_project_assigned(check_project_id uuid) IS 'Checks if the current user is assigned to a specific project. Uses SECURITY DEFINER to bypass RLS and prevent circular dependency.';

-- FUNCTION: user_is_project_creator(uuid)
CREATE FUNCTION project.user_is_project_creator(check_project_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM project.projects
    WHERE id = check_project_id
    AND created_by = project.current_user_id()
  );
END;
$$;

-- COMMENT: FUNCTION user_is_project_creator(check_project_id uuid)
COMMENT ON FUNCTION project.user_is_project_creator(check_project_id uuid) IS 'Checks if the current user created a specific project. Uses SECURITY DEFINER to bypass RLS and prevent circular dependency.';

-- FUNCTION: user_is_superadmin()
CREATE FUNCTION project.user_is_superadmin() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
BEGIN
  -- Fast path: Check is_superadmin flag first
  IF EXISTS (
    SELECT 1 FROM project.user_profiles
    WHERE id = project.current_user_id()
    AND is_superadmin = TRUE
  ) THEN
    RETURN TRUE;
  END IF;

  -- Fallback: Check for Superadmin role (legacy support)
  -- Bypasses RLS via SECURITY DEFINER
  RETURN EXISTS (
    SELECT 1
    FROM project.user_roles ur
    JOIN project.roles r ON ur.role_id = r.id
    WHERE ur.user_id = project.current_user_id()
    AND r.is_system_role = TRUE
    AND LOWER(r.name) = 'superadmin'
  );
END;
$$;

-- COMMENT: FUNCTION user_is_superadmin()
COMMENT ON FUNCTION project.user_is_superadmin() IS 'Checks if the current user is a superadmin. Uses SECURITY DEFINER to bypass RLS and prevent circular dependency.';

-- FUNCTION: user_is_valid_task_member(uuid, uuid)
CREATE FUNCTION project.user_is_valid_task_member(pid uuid, uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
  SELECT uid IS NOT NULL
    AND EXISTS (SELECT 1 FROM project.user_profiles up
                WHERE up.id = uid AND NOT COALESCE(up.is_client, false) AND up.is_active IS NOT FALSE)
    AND (
         EXISTS (SELECT 1 FROM project.projects p WHERE p.id = pid AND (p.created_by = uid OR p.assigned_user_id = uid))
      OR EXISTS (SELECT 1 FROM project.project_assignments pa
                 WHERE pa.project_id = pid AND pa.user_id = uid AND pa.removed_at IS NULL)
    );
$$;

-- FUNCTION: validate_task_dependency()
CREATE FUNCTION project.validate_task_dependency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE pid uuid;
BEGIN
  IF NEW.task_id = NEW.depends_on_task_id THEN
    RAISE EXCEPTION 'A task cannot depend on itself' USING ERRCODE = '23514';
  END IF;
  pid := project.task_project(NEW.task_id);
  IF pid IS DISTINCT FROM project.task_project(NEW.depends_on_task_id) THEN
    RAISE EXCEPTION 'Dependencies must be within the same project' USING ERRCODE = '23514';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('task_dependencies:' || pid::text));
  IF EXISTS (
    WITH RECURSIVE reach(id) AS (
      SELECT NEW.depends_on_task_id
      UNION
      SELECT d.depends_on_task_id
      FROM project.task_dependencies d
      JOIN reach r ON d.task_id = r.id
      WHERE d.id IS DISTINCT FROM NEW.id
    )
    SELECT 1 FROM reach WHERE id = NEW.task_id
  ) THEN
    RAISE EXCEPTION 'This dependency would create a cycle' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: validate_task_parent()
CREATE FUNCTION project.validate_task_parent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
DECLARE p_project uuid; p_parent uuid;
BEGIN
  IF NEW.parent_task_id IS NULL THEN RETURN NEW; END IF;
  SELECT project_id, parent_task_id INTO p_project, p_parent FROM project.tasks WHERE id = NEW.parent_task_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent task not found' USING ERRCODE = '23503'; END IF;
  IF p_project <> NEW.project_id THEN RAISE EXCEPTION 'Parent task must be in the same project' USING ERRCODE = '23514'; END IF;
  IF p_parent IS NOT NULL THEN RAISE EXCEPTION 'Subtasks cannot have their own subtasks' USING ERRCODE = '23514'; END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: workflow_instance_project(uuid)
CREATE FUNCTION project.workflow_instance_project(iid uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'project', 'pg_temp'
    AS $$
  SELECT project_id FROM project.workflow_instances WHERE id = iid;
$$;


