    CONSTRAINT task_activity_action_check CHECK ((action = ANY (ARRAY['created'::text, 'status_changed'::text, 'assigned'::text, 'priority_changed'::text, 'progress_updated'::text, 'review_submitted'::text, 'review_approved'::text, 'changes_requested'::text, 'reopened'::text])))
);

