-- TABLE: tasks
CREATE TABLE project.tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    description text,
    project_id uuid NOT NULL,
    status text DEFAULT 'todo'::text,
    priority text DEFAULT 'medium'::text,
    start_date date,
    due_date date,
    estimated_hours numeric(10,2),
    actual_hours numeric(10,2) DEFAULT 0,
    remaining_hours numeric(10,2),
    assigned_to uuid,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    display_order integer DEFAULT 0,
    parent_task_id uuid,
    reviewer_id uuid,
    review_note text,
    progress_percent smallint DEFAULT 0 NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    CONSTRAINT tasks_parent_not_self CHECK (((parent_task_id IS NULL) OR (parent_task_id <> id))),
    CONSTRAINT tasks_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT tasks_progress_check CHECK (((progress_percent >= 0) AND (progress_percent <= 100))),
    CONSTRAINT tasks_review_note_len CHECK (((review_note IS NULL) OR (char_length(review_note) <= 2000))),
    CONSTRAINT tasks_status_check CHECK ((status = ANY (ARRAY['todo'::text, 'in_progress'::text, 'on_hold'::text, 'review'::text, 'changes_requested'::text, 'done'::text, 'backlog'::text, 'blocked'::text])))
);

