-- VIEW: weekly_capacity_summary
CREATE VIEW project.weekly_capacity_summary AS
 SELECT ua.user_id,
    ua.week_start_date,
    ua.available_hours,
    COALESCE(sum(twa.allocated_hours), (0)::numeric) AS allocated_hours,
    COALESCE(sum(te.hours_logged), (0)::numeric) AS actual_hours,
        CASE
            WHEN (ua.available_hours > (0)::numeric) THEN ((COALESCE(sum(te.hours_logged), (0)::numeric) / ua.available_hours) * (100)::numeric)
            ELSE (0)::numeric
        END AS utilization_rate,
    (ua.available_hours - COALESCE(sum(te.hours_logged), (0)::numeric)) AS remaining_capacity,
        CASE
            WHEN (COALESCE(sum(twa.allocated_hours), (0)::numeric) > ua.available_hours) THEN true
            ELSE false
        END AS is_over_allocated,
    count(DISTINCT twa.task_id) AS active_task_count
   FROM ((project.user_availability ua
     LEFT JOIN project.task_week_allocations twa ON (((twa.assigned_user_id = ua.user_id) AND (twa.week_start_date = ua.week_start_date))))
     LEFT JOIN project.time_entries te ON (((te.user_id = ua.user_id) AND (te.week_start_date = ua.week_start_date))))
  GROUP BY ua.user_id, ua.week_start_date, ua.available_hours;

-- COMMENT: VIEW weekly_capacity_summary
COMMENT ON VIEW project.weekly_capacity_summary IS 'Aggregates weekly capacity metrics for users including availability, allocations, actual hours, and utilization rate.';

